from pathlib import Path
import html

ROOT = Path(__file__).resolve().parents[1]
rows = [
 ('Sint Maartenskliniek', '30 participants; 20 healthy / 10 stroke; compatible bilateral wearable-IMU mapping', 'No subject-level age/sex table in the public release', 'Direct external evaluation and training sensitivity', 'Cannot support age-stratified performance until demographic linkage is obtained.'),
 ('Zhou rehabilitation', '10 stroke participants; ages 37–88; 7 male / 3 female; FAC 1–5', 'Age and sex available, but stroke-only and repeated visits', 'Severity, recovery, and longitudinal analysis', 'Cannot create healthy-vs-stroke age cells by itself.'),
 ('Triaxial healthy reference', '60 healthy participants; ages 65–88', 'Age available; healthy-only; channel layout incompatible with LB/LF/RF', 'Older-healthy domain and age reference', 'Cannot directly score or train the current classifier.'),
 ('Mobilise-D CVS', '2,315 participants; COPD/MS/PD/PFF; ages 21–96; rich demographics', 'No stroke or healthy control cohort; processed single-back DMO', 'Clinical specificity and population stress testing', 'Cannot provide age-stratified stroke-vs-healthy performance.'),
 ('Voisard wider release', '259 valid-age participants; ages 18–90; mixed healthy/neurological/orthopaedic groups', 'Age coverage is wider, but binary stroke/healthy linkage is incomplete', 'Age confounding and descriptive coverage', 'Requires verified subject-level label-age linkage before subgroup evaluation.'),
]
def e(x): return html.escape(str(x))
tr = ''.join(f'<tr><td><strong>{e(a)}</strong></td><td>{e(b)}</td><td>{e(c)}</td><td>{e(d)}</td><td>{e(f)}</td></tr>' for a,b,c,d,f in rows)
html_text = f'''<!doctype html><html><head><meta charset="utf-8"><title>New Dataset Demographic Role Matrix</title><style>body{{font-family:Segoe UI,Arial;background:#f5f7fb;color:#172033;margin:30px}}.wrap{{max-width:1450px;margin:auto}}.hero{{background:#102a43;color:#fff;padding:26px 30px;border-radius:14px}}.decision{{background:#eaf7f7;border-left:6px solid #0f8b8d;padding:18px;margin:18px 0;line-height:1.5}}.box{{background:#fff;border:1px solid #dce4ed;border-radius:12px;overflow:auto}}table{{border-collapse:collapse;width:100%;min-width:1200px}}th{{background:#173f5f;color:#fff;text-align:left;padding:12px}}td{{padding:12px;border-bottom:1px solid #e5eaf0;vertical-align:top;line-height:1.4}}tr:nth-child(even){{background:#f8fafc}}.foot{{color:#53657a;font-size:13px;margin-top:16px}}</style></head><body><div class="wrap"><div class="hero"><h1>New Dataset Demographic Role Matrix</h1><p>What each recruited public source can and cannot contribute to demographic validation.</p></div><div class="decision"><strong>Answer:</strong> The new datasets are useful, but they do not collectively provide a complete age-stratified stroke-versus-healthy test. Sint improves compatible model robustness; Zhou improves stroke severity evidence; Triaxial improves older-healthy coverage; Mobilise-D improves clinical specificity; Voisard provides wider age context. A balanced age-labelled stroke and healthy source is still missing.</div><div class="box"><table><tr><th>Dataset</th><th>Coverage</th><th>Demographic limitation</th><th>Correct role</th><th>Why it cannot finish age validation alone</th></tr>{tr}</table></div><p class="foot">This matrix prevents useful datasets from being discarded while avoiding invalid pooling or unsupported subgroup claims.</p></div></body></html>'''
out = ROOT / 'reports/NEW_DATASET_DEMOGRAPHIC_ROLE_MATRIX.html'
out.write_text(html_text, encoding='utf-8')
print(out)
